import json


def lambda_handler(event, context):
    """Handle an ALB request and return a valid ALB Lambda response."""
    return {
        "statusCode": 200,
        "statusDescription": "200 OK",
        "isBase64Encoded": False,
        "headers": {
            "Content-Type": "text/html; charset=utf-8"
        },
        "body": "<html><body><h1>Hello from Lambda behind an ALB</h1><p>Environment: demo</p></body></html>"
    }
